// CoreServiceServer is the server API for CoreService service.
// All implementations must embed UnimplementedCoreServiceServer
// for forward compatibility.
//
// CoreService owns users, plans, orders, wallet ledger, subscriptions,
// audit log, branding/settings, and the dashboard API backing store.
type CoreServiceServer interface {
	UpsertUser(context.Context, *UpsertUserRequest) (*User, error)
	GetUser(context.Context, *GetUserRequest) (*User, error)
	ListPlans(context.Context, *ListPlansRequest) (*ListPlansResponse, error)
	CreateOrder(context.Context, *CreateOrderRequest) (*Order, error)
	GetOrder(context.Context, *GetOrderRequest) (*Order, error)
	GetWallet(context.Context, *GetWalletRequest) (*Wallet, error)
	ListLedgerEntries(context.Context, *ListLedgerEntriesRequest) (*ListLedgerEntriesResponse, error)
	ListSubscriptions(context.Context, *ListSubscriptionsRequest) (*ListSubscriptionsResponse, error)
	CreateSupportTicket(context.Context, *CreateSupportTicketRequest) (*Ticket, error)
	GetSettings(context.Context, *GetSettingsRequest) (*Settings, error)
	// Deprecated: Do not use.
	// UpdateBranding is not served (Unimplemented): branding is changed with
	// AdminSetSetting or the dashboard, which check and audit every value.
	UpdateBranding(context.Context, *UpdateBrandingRequest) (*Settings, error)
	ReviewManualPayment(context.Context, *ReviewManualPaymentRequest) (*PaymentIntentRef, error)
	PayOrderWithWallet(context.Context, *PayOrderWithWalletRequest) (*Order, error)
	CreatePaymentIntent(context.Context, *CreatePaymentIntentRequest) (*PaymentIntentRef, error)
	StartTrial(context.Context, *StartTrialRequest) (*Order, error)
	CanStartTrial(context.Context, *CanStartTrialRequest) (*CanStartTrialResponse, error)
	SubmitPaymentProof(context.Context, *SubmitPaymentProofRequest) (*PaymentIntentRef, error)
	CheckPayment(context.Context, *CheckPaymentRequest) (*PaymentIntentRef, error)
	StarsPreCheckout(context.Context, *StarsPreCheckoutRequest) (*PaymentIntentRef, error)
	StarsPaid(context.Context, *StarsPaidRequest) (*PaymentIntentRef, error)
	ListPaymentMethods(context.Context, *ListPaymentMethodsRequest) (*ListPaymentMethodsResponse, error)
	GetSubscriptionLinks(context.Context, *GetSubscriptionLinksRequest) (*SubscriptionLinks, error)
	AdminGetStats(context.Context, *AdminGetStatsRequest) (*AdminStats, error)
	AdminListPendingPayments(context.Context, *AdminListPendingPaymentsRequest) (*AdminListPendingPaymentsResponse, error)
	AdminFindUser(context.Context, *AdminFindUserRequest) (*AdminUserView, error)
	AdminAdjustBalance(context.Context, *AdminAdjustBalanceRequest) (*Wallet, error)
	AdminSetUserStatus(context.Context, *AdminSetUserStatusRequest) (*User, error)
	AdminUpsertPlan(context.Context, *AdminUpsertPlanRequest) (*Plan, error)
	AdminSetSetting(context.Context, *AdminSetSettingRequest) (*Settings, error)
	QuoteOrder(context.Context, *QuoteOrderRequest) (*Quote, error)
	GetReferralInfo(context.Context, *GetReferralInfoRequest) (*ReferralInfo, error)
	AdminUpsertDiscount(context.Context, *AdminUpsertDiscountRequest) (*Discount, error)
	AdminListDiscounts(context.Context, *AdminListDiscountsRequest) (*AdminListDiscountsResponse, error)
	CreateDashboardLink(context.Context, *CreateDashboardLinkRequest) (*DashboardLink, error)
	// ListStaffContacts lists the active owners and admins, for staff alerts.
	ListStaffContacts(context.Context, *ListStaffContactsRequest) (*ListStaffContactsResponse, error)
	// Support tickets (milestone 4). CreateSupportTicket stays for older bots.
	AddTicketMessage(context.Context, *AddTicketMessageRequest) (*AddTicketMessageResponse, error)
	GetMyTickets(context.Context, *GetMyTicketsRequest) (*MyTickets, error)
	GetMyTicket(context.Context, *GetMyTicketRequest) (*TicketThread, error)
	CloseMyTicket(context.Context, *CloseMyTicketRequest) (*Ticket, error)
	GetTicketMessage(context.Context, *GetTicketMessageRequest) (*TicketMessageView, error)
	ReportTicketDelivery(context.Context, *ReportTicketDeliveryRequest) (*ReportTicketDeliveryResponse, error)
	// Broadcasts (milestone 4): the bot claims recipients and reports results.
	SetUserBotBlocked(context.Context, *SetUserBotBlockedRequest) (*SetUserBotBlockedResponse, error)
	ClaimBroadcastBatch(context.Context, *ClaimBroadcastBatchRequest) (*BroadcastBatch, error)
	ReportBroadcastResults(context.Context, *ReportBroadcastResultsRequest) (*BroadcastState, error)
	// Resellers (milestone 5).
	SetSubscriptionLabel(context.Context, *SetSubscriptionLabelRequest) (*Subscription, error)
	GetResellerInfo(context.Context, *GetResellerInfoRequest) (*ResellerInfo, error)
	// GetBotPhoto returns the bot photo, for the bot to set in Telegram when
	// Settings.bot_photo_version changes; NOT_FOUND when there is none.
	GetBotPhoto(context.Context, *GetBotPhotoRequest) (*BotPhoto, error)
	mustEmbedUnimplementedCoreServiceServer()
}

